package server

const pageTemplate = `{{define "page"}}<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{{.Saga.Manifest.Title}} · Review Saga</title>
<style>
:root{--ink:#18231d;--muted:#68746d;--paper:#f4f2eb;--card:#fffefa;--line:#d8d2c3;--accent:#14614d;--accent-soft:#e4efe9;--red:#a83c2d;--amber:#a66a09;--green:#267447;--code:#202620;--shadow:0 14px 38px #18231d14}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.55 system-ui,sans-serif}button,input,textarea{font:inherit}button{cursor:pointer}.topbar{position:sticky;top:0;z-index:30;height:58px;display:flex;align-items:center;gap:20px;padding:0 22px;background:#18231df5;color:white;border-bottom:1px solid #ffffff1a}.brand{font:700 12px monospace;letter-spacing:.13em;text-transform:uppercase}.view-tabs{display:flex;align-self:stretch}.view-tab{border:0;border-bottom:3px solid transparent;padding:0 18px;background:transparent;color:#bdc8c1;font-weight:650}.view-tab.active{color:white;border-color:#8ed3b0}.top-meta{margin-left:auto;color:#aebbb4;font:12px monospace}.shell{display:grid;grid-template-columns:270px minmax(0,1fr);min-height:calc(100vh - 58px)}.sidebar{position:sticky;top:58px;height:calc(100vh - 58px);overflow:auto;padding:24px 20px;background:#ebe7db;border-right:1px solid var(--line)}.sidebar h1{font:600 24px/1.2 Georgia,serif;margin:6px 0 12px}.range{font:11px/1.5 monospace;color:var(--muted);overflow-wrap:anywhere}.side-label{margin:24px 0 8px;font:700 10px monospace;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}nav a,.file-tree a{display:flex;gap:8px;align-items:center;padding:6px 8px;margin:2px -8px;text-decoration:none;color:var(--ink);border-radius:7px}.file-tree a:hover,nav a:hover{background:#ded9cc}.nav-child{padding-left:13px}.file-tree .reviewed{color:var(--green)}.file-tree code{font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.file-tree .counts{margin-left:auto;white-space:nowrap;font:10px monospace}.content{width:min(1180px,100%);padding:36px clamp(18px,5vw,64px) 90px}.view{display:none}.view.active{display:block}.summary{background:var(--ink);color:white;border-radius:18px;padding:24px 28px;display:grid;grid-template-columns:1fr auto;gap:18px;box-shadow:var(--shadow)}.summary h2{font:500 27px Georgia,serif;margin:0}.score{font:700 34px monospace;color:#aee7ca}.bar{grid-column:1/-1;height:7px;background:#46534b;border-radius:9px;overflow:hidden}.bar span{display:block;width:{{.Percent}}%;height:100%;background:#9be0bd}.metrics{display:flex;gap:9px;flex-wrap:wrap;margin:14px 0 30px}.metric{padding:5px 10px;border:1px solid var(--line);border-radius:99px;color:var(--muted)}.alert,.remaining{background:#fff7e8;border:1px solid #dfcda7;border-radius:11px;padding:14px;margin:16px 0}.section{scroll-margin-top:75px;margin:26px 0}.section-head{display:flex;justify-content:space-between;align-items:center;gap:16px;border-bottom:1px solid var(--line);padding-bottom:9px}.section-title{display:flex;align-items:baseline;gap:10px}.section h2{font:500 34px Georgia,serif;margin:0}.path{color:var(--muted);font:12px monospace}.review-status{font:11px monospace;text-transform:uppercase;color:var(--accent)}.review-form{display:flex;gap:5px;flex-wrap:wrap;margin:8px 0}.review-form input{padding:6px;min-width:120px}.fragment{position:relative;scroll-margin-top:75px;background:var(--card);border:1px solid var(--line);border-radius:15px;margin:18px 0;padding:22px;box-shadow:var(--shadow)}.fragment-head{display:flex;justify-content:space-between;gap:12px;align-items:center}.fragment h3{margin:0;font:650 13px system-ui;text-transform:uppercase;letter-spacing:.07em;color:var(--muted)}.tools{display:flex;gap:5px;flex-wrap:wrap}.btn,button{font:650 12px system-ui;border:0;border-radius:7px;padding:7px 10px;background:var(--accent);color:white}.btn-subtle,.tools button{background:var(--accent-soft);color:var(--accent)}.diff-button{display:inline-flex;align-items:center;gap:6px}.diff-button svg{width:14px;height:14px}.fragment-stage{position:relative;margin-top:14px;min-height:70px}.fragment-frame{display:block;width:100%;min-height:430px;border:0;border-radius:9px;background:white}.fragment-image{display:block;max-width:100%;height:auto;margin:auto}.fragment-markdown{font:17px/1.7 Georgia,serif}.fragment-markdown pre,.plain{overflow:auto;background:#eeebe2;padding:12px;border-radius:8px;font:13px/1.5 monospace}.review-overlay{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible}.review-overlay.drawing{pointer-events:auto;cursor:crosshair;background:#14614d0a}.annotation{fill:#ffcc0038;stroke:#d04832;stroke-width:5;vector-effect:non-scaling-stroke}.annotation.path{fill:none}.pending{stroke:#14614d;fill:#14614d20}.composer{display:none;margin-top:12px;padding:12px;background:#edf4ef;border-radius:9px}.composer.open{display:block}.composer-grid{display:grid;grid-template-columns:160px 1fr;gap:8px}.composer input,.composer textarea,.diff-compose input,.diff-compose textarea,.review-form input,.reply input{width:100%;padding:8px;border:1px solid #bbb6aa;border-radius:7px}.composer textarea,.diff-compose textarea{min-height:68px}.threads{margin-top:14px}.thread{border-left:3px solid #d59b28;padding:8px 12px;margin:9px 0;background:#fffaf0}.thread.suggestion{border-color:#5981bd}.thread.resolved{opacity:.65;border-color:#87948c}.thread-meta{font:11px monospace;color:var(--muted)}.suggestion-code{display:block;margin:8px 0;padding:10px;background:#e6f3ea;color:#174a2b;border-radius:6px;white-space:pre-wrap}.message{margin:8px 0;padding-top:7px;border-top:1px solid var(--line)}.message-fragment iframe{min-height:240px}.reply{display:grid;grid-template-columns:130px 1fr auto;gap:6px;margin-top:8px}.text-anchor{background:#ffe797;padding:2px 5px;font-size:12px}.diff-drawer{position:fixed;z-index:80;inset:58px 0 0 auto;width:min(780px,94vw);background:#f8f7f2;box-shadow:-18px 0 55px #18231d30;transform:translateX(105%);transition:transform .22s ease;display:flex;flex-direction:column}.diff-drawer.open{transform:none}.drawer-backdrop{position:fixed;z-index:70;inset:58px 0 0;background:#18231d55;display:none}.drawer-backdrop.open{display:block}.drawer-head{display:flex;align-items:center;gap:12px;padding:16px 20px;border-bottom:1px solid var(--line);background:white}.drawer-head h2{font:600 18px Georgia,serif;margin:0}.drawer-head button{margin-left:auto;background:#e8e6df;color:var(--ink)}.drawer-body{overflow:auto;padding:18px 20px 100px}.code-heading{display:flex;align-items:end;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:14px;margin-bottom:18px}.code-heading h2{font:500 32px Georgia,serif;margin:0}.file-diff{scroll-margin-top:76px;margin:0 0 24px;border:1px solid #c8c4b9;border-radius:11px;overflow:hidden;background:white}.file-head{position:sticky;top:58px;z-index:5;display:flex;align-items:center;gap:12px;padding:11px 14px;background:#eceae3;border-bottom:1px solid #c8c4b9}.file-head code{font-weight:700;overflow-wrap:anywhere}.file-head .counts{margin-left:auto;font:12px monospace}.reviewed-badge{color:var(--green);font:700 11px monospace;text-transform:uppercase}.file-review{display:flex;gap:6px}.file-review input{width:105px;padding:5px;border:1px solid #aaa;border-radius:6px}.diff-lines{background:var(--code);color:#dce5dd}.diff-row{display:grid;grid-template-columns:54px 22px minmax(0,1fr) auto;align-items:start;min-height:29px;border-top:1px solid #ffffff0a;font:12px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace}.diff-row:first-child{border-top:0}.diff-row.new{background:#173a28}.diff-row.old{background:#442522}.diff-row.event{background:#2b332d;color:#b9c5bd}.line-no{padding:5px 8px;text-align:right;color:#8e9b92;user-select:none}.sign{padding:5px 0;color:#aab7ae}.code-line{padding:5px 9px;white-space:pre-wrap;overflow-wrap:anywhere}.line-actions{display:flex;gap:3px;padding:3px 5px;opacity:0}.diff-row:hover .line-actions,.diff-row:focus-within .line-actions{opacity:1}.line-actions button{padding:3px 6px;background:#ffffff18;color:white;font:11px system-ui}.diff-thread-wrap{grid-column:3/5;padding:0 10px 8px}.diff-compose{position:fixed;z-index:100;right:24px;bottom:20px;width:min(520px,calc(100vw - 48px));padding:15px;background:white;border:1px solid var(--line);border-radius:12px;box-shadow:0 18px 65px #18231d4a;display:none}.diff-compose.open{display:block}.diff-compose-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:9px}.diff-compose-head strong{font:600 15px Georgia,serif}.diff-compose-head button{background:#e8e6df;color:var(--ink)}.diff-compose-fields{display:grid;grid-template-columns:130px 1fr;gap:7px}.replacement{display:none;grid-column:1/-1}.diff-compose.suggesting .replacement{display:block}.footer{text-align:center;color:var(--muted);font-size:12px;margin-top:35px}@media(max-width:780px){.shell{display:block}.sidebar{position:static;height:auto}.sidebar nav{display:none}.content{padding:22px 12px}.composer-grid,.reply,.diff-compose-fields{grid-template-columns:1fr}.top-meta{display:none}.section h2{font-size:27px}.file-head{top:58px}.line-actions{opacity:1}.diff-row{grid-template-columns:42px 18px minmax(0,1fr)}.line-actions{grid-column:3}.diff-thread-wrap{grid-column:3}}
</style><script src="/app.js" defer></script></head><body>
<header class="topbar"><div class="brand">Review Saga</div><div class="view-tabs"><button class="view-tab active" data-view-tab="saga">Saga</button><button class="view-tab" data-view-tab="code">Code Diff</button></div><div class="top-meta">{{len .Files}} files · {{.ReviewedFiles}} reviewed</div></header>
<div class="shell"><aside class="sidebar"><h1>{{.Saga.Manifest.Title}}</h1><div class="range">{{.Saga.Manifest.Source.Repository}}<br>{{.Saga.Manifest.Source.Base}} … {{.Saga.Manifest.Source.Head}}</div><div class="saga-side"><div class="side-label">Story</div><nav>{{template "nav" .Root}}</nav></div><div class="code-side" hidden><div class="side-label">Changed files</div><div class="file-tree">{{range .Files}}<a class="{{if .Reviewed}}reviewed{{end}}" href="#{{.ID}}"><span>{{if .Reviewed}}✓{{else}}◇{{end}}</span><code>{{.Path}}</code><span class="counts">+{{.Added}} −{{.Deleted}}</span></a>{{end}}</div></div></aside>
<main class="content"><div class="view active" data-view="saga"><section class="summary"><h2>{{if .Report.Complete}}Every source change is accounted for.{{else}}The story still has gaps.{{end}}</h2><div class="score">{{.Percent}}%</div><div class="bar"><span></span></div></section><div class="metrics"><span class="metric">{{.Report.Summary.Uncovered}} uncovered</span><span class="metric">{{.Report.Summary.Orphaned}} stale URIs</span><span class="metric">{{len .Saga.Threads}} review threads</span></div>{{if .Error}}<div class="alert"><strong>Source comparison failed.</strong> {{.Error}}</div>{{end}}{{if .Report.Uncovered}}<details class="remaining"><summary>{{len .Report.Uncovered}} unaccounted changes</summary>{{range .Report.Uncovered}}<code>{{.Path}}:{{.Line}} {{.Side}}</code><br>{{end}}</details>{{end}}{{template "section" .Root}}</div>
<div class="view" data-view="code"><div class="code-heading"><div><div class="side-label">Complete comparison</div><h2>Code Diff</h2></div><span class="metric">{{.ReviewedFiles}} / {{len .Files}} files reviewed</span></div>{{range .Files}}{{template "file-diff" .}}{{else}}<div class="remaining">No product code changes in this comparison.</div>{{end}}</div><div class="footer">Generated {{.Generated.Format "2006-01-02 15:04:05 MST"}} · {{.SchemaInfo}}</div></main></div>
<div class="drawer-backdrop" data-close-drawer></div><aside class="diff-drawer" aria-hidden="true"><div class="drawer-head"><div><div class="side-label">Attached code</div><h2>Linked diffs</h2></div><button type="button" data-close-drawer>Close</button></div><div class="drawer-body"></div></aside>
<form class="diff-compose" method="post" action="/api/thread" enctype="multipart/form-data"><input type="hidden" name="target"><input type="hidden" name="anchor"><input type="hidden" name="kind" value="comment"><div class="diff-compose-head"><strong>Comment on this change</strong><button type="button" data-close-diff-compose>Cancel</button></div><div class="diff-compose-fields"><input required name="author" placeholder="Your name"><textarea name="body" placeholder="What should the author know?"></textarea><textarea class="replacement" name="replacement" placeholder="Replacement code"></textarea><input type="file" name="attachment" accept="image/*,.svg,.html,.txt" multiple><button type="submit">Add to review</button></div></form>
</body></html>{{end}}

{{define "nav"}}<a href="#{{.DOMID}}">{{if eq .Kind "chapter"}}<strong>Chapter</strong>{{end}} {{.Title}}</a>{{range .FragmentViews}}<a class="nav-child" href="#{{.DOMID}}">{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}</a>{{end}}{{if .ChildViews}}<div class="nav-child">{{range .ChildViews}}{{template "nav" .}}{{end}}</div>{{end}}{{end}}

{{define "diff-icon"}}<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M8 3v12a4 4 0 0 0 4 4h4M5 6l3-3 3 3M13 16l3 3-3 3"/></svg>{{end}}

{{define "section"}}<section class="section {{.Kind}}" id="{{.DOMID}}"><div class="section-head"><div class="section-title">{{if eq .Kind "chapter"}}<span class="review-status">Chapter</span>{{end}}<h2>{{.Title}}</h2><span class="path">{{.DisplayPath}}</span></div>{{if .Changes}}<button class="btn-subtle diff-button" type="button" data-open-diffs="diffs-{{.DOMID}}">{{template "diff-icon"}} {{len .Changes}}</button>{{end}}</div>{{if .ReviewState}}<div class="review-status">{{.ReviewState}} by {{.ReviewAuthor}}</div>{{end}}<form class="review-form" method="post" action="/api/review"><input type="hidden" name="target" value="{{.Target}}"><input required name="author" placeholder="Your name"><input name="body" placeholder="Optional review note"><button name="state" value="approved">Approve{{if eq .Kind "chapter"}} chapter{{end}}</button><button name="state" value="rejected">Request changes</button><button name="state" value="closed">Close</button></form>{{template "threads" .Threads}}{{range .FragmentViews}}{{template "fragment" .}}{{end}}{{if .Changes}}<template id="diffs-{{.DOMID}}"><div class="file-diff"><div class="file-head"><code>{{.DisplayPath}} attached changes</code><span class="counts">{{len .Changes}} changes</span></div><div class="diff-lines">{{range .Changes}}{{template "diff-row" .}}{{end}}</div></div></template>{{end}}</section>{{range .ChildViews}}{{template "section" .}}{{end}}{{end}}

{{define "fragment"}}<article class="fragment" id="{{.DOMID}}" data-target="{{.Target}}"><div class="fragment-head"><div><h3>{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}} · {{.MediaType}}</h3>{{if .ReviewState}}<div class="review-status">{{.ReviewState}} by {{.ReviewAuthor}}</div>{{end}}</div><div class="tools"><button type="button" class="diff-button" data-open-diffs="diffs-{{.DOMID}}">{{template "diff-icon"}} {{len .Changes}}</button><button type="button" data-annotate="target">Comment</button><button type="button" data-annotate="rect">Rectangle</button><button type="button" data-annotate="draw">Draw</button>{{if .Markdown}}<button type="button" data-annotate="text">Highlight</button>{{end}}</div></div>
<div class="fragment-stage">{{if .Markdown}}<div class="fragment-markdown" data-selectable>{{.Markdown}}</div>{{else if .Plain}}<pre class="plain" data-selectable>{{.Plain}}</pre>{{else if .Interactive}}<iframe class="fragment-frame" sandbox="allow-scripts" src="{{.URL}}" title="{{.Title}}"></iframe>{{else if .Image}}<img class="fragment-image" src="{{.URL}}" alt="{{.Title}}">{{else}}<a href="{{.URL}}">Open fragment</a>{{end}}<svg class="review-overlay" viewBox="0 0 1000 1000" preserveAspectRatio="none">{{range .Threads}}{{range .Anchor.Shapes}}{{if eq .Type "rect"}}<rect class="annotation" x="{{coord .X}}" y="{{coord .Y}}" width="{{coord .Width}}" height="{{coord .Height}}"/>{{else if eq .Type "ellipse"}}<ellipse class="annotation" cx="{{coord .X}}" cy="{{coord .Y}}" rx="{{coord .Width}}" ry="{{coord .Height}}"/>{{else if eq .Type "line"}}<line class="annotation path" x1="{{coord .X}}" y1="{{coord .Y}}" x2="{{coord .Width}}" y2="{{coord .Height}}"/>{{else if eq .Type "path"}}<polyline class="annotation path" points="{{points .Points}}"/>{{end}}{{end}}{{end}}</svg></div>
<form class="composer" method="post" action="/api/thread" enctype="multipart/form-data"><input type="hidden" name="target" value="{{.Target}}"><input type="hidden" name="anchor" value='{"type":"target"}'><input type="hidden" name="kind" value="comment"><div class="composer-grid"><input required name="author" placeholder="Your name"><textarea name="body" placeholder="Start a review thread"></textarea></div><input type="file" name="attachment" accept="image/*,.svg,.html,.txt" multiple><button type="submit">Create thread</button></form>
<form class="review-form" method="post" action="/api/review"><input type="hidden" name="target" value="{{.Target}}"><input required name="author" placeholder="Your name"><input name="body" placeholder="Fragment review note"><button name="state" value="approved">Approve fragment</button><button name="state" value="rejected">Request changes</button></form>{{template "threads" .Threads}}<template id="diffs-{{.DOMID}}">{{if .Changes}}<div class="file-diff"><div class="file-head"><code>{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}} attached changes</code><span class="counts">{{len .Changes}} changes</span></div><div class="diff-lines">{{range .Changes}}{{template "diff-row" .}}{{end}}</div></div>{{else}}<div class="remaining">No diff lines are attached to this fragment yet.</div>{{end}}</template></article>{{end}}

{{define "file-diff"}}<article class="file-diff" id="{{.ID}}"><header class="file-head"><code>{{.Path}}</code>{{if .Reviewed}}<span class="reviewed-badge">✓ Reviewed{{if .Reviewer}} by {{.Reviewer}}{{end}}</span>{{end}}<span class="counts">+{{.Added}} −{{.Deleted}}</span><form class="file-review" method="post" action="/api/diff-review"><input type="hidden" name="uri" value="{{.URI}}"><input type="hidden" name="file" value="{{.ID}}"><input required name="author" placeholder="Your name"><button name="state" value="{{if .Reviewed}}unreviewed{{else}}reviewed{{end}}">{{if .Reviewed}}Unmark{{else}}Mark reviewed{{end}}</button></form></header><div class="diff-lines">{{range .Atoms}}{{template "diff-row" .}}{{end}}</div></article>{{end}}

{{define "diff-row"}}{{if eq .Kind "event"}}<div class="diff-row event"><span class="line-no">•</span><span class="sign">↳</span><span class="code-line">{{.Event}} {{if .OldPath}}{{.OldPath}} → {{.NewPath}}{{else}}{{.Path}}{{end}}</span><span class="line-actions"><button type="button" data-diff-action="comment" data-uri="{{.URI}}" data-target="{{.Target}}">Comment</button></span>{{template "diff-threads" .Threads}}</div>{{else}}<div class="diff-row {{.Side}}"><span class="line-no">{{.Line}}</span><span class="sign">{{if eq .Side "new"}}+{{else}}−{{end}}</span><span class="code-line">{{.Content}}</span><span class="line-actions"><button type="button" data-diff-action="comment" data-uri="{{.URI}}" data-target="{{.Target}}">Comment</button><button type="button" data-diff-action="suggestion" data-uri="{{.URI}}" data-target="{{.Target}}" data-content="{{.Content}}">Suggest</button></span>{{template "diff-threads" .Threads}}</div>{{end}}{{end}}

{{define "diff-threads"}}{{if .}}<div class="diff-thread-wrap">{{template "threads" .}}</div>{{end}}{{end}}

{{define "threads"}}{{if .}}<div class="threads">{{range .}}{{$thread := .}}<article class="thread {{.State}} {{.Kind}}"><div class="thread-meta">{{.CreatedBy}} · {{.CreatedAt.Format "2006-01-02 15:04 MST"}} · {{if .Kind}}{{.Kind}}{{else}}{{.Anchor.Type}}{{end}} · {{.State}}</div>{{if .Anchor.Text}}<div class="text-anchor" data-text-target="{{.Target}}" data-exact="{{.Anchor.Text.Exact}}">“{{.Anchor.Text.Exact}}”</div>{{end}}{{if .Suggestion}}<code class="suggestion-code">{{.Suggestion.Replacement}}</code>{{end}}{{range $index,$message := .Messages}}<div class="message"><div class="thread-meta">{{$message.Author}} · {{$message.CreatedAt.Format "2006-01-02 15:04 MST"}}</div>{{range index $thread.MessageViews $index}}<div class="message-fragment">{{if .Markdown}}<div class="fragment-markdown">{{.Markdown}}</div>{{else if .Interactive}}<iframe class="fragment-frame" sandbox="allow-scripts" src="{{.URL}}"></iframe>{{else if .Image}}<img class="fragment-image" src="{{.URL}}" alt="attachment">{{else}}<pre class="plain">{{.Plain}}</pre>{{end}}</div>{{end}}</div>{{end}}<form class="reply" method="post" action="/api/reply" enctype="multipart/form-data"><input type="hidden" name="thread" value="{{.ID}}"><input type="hidden" name="target" value="{{.Target}}"><input required name="author" placeholder="Your name"><input name="body" placeholder="Reply"><button>Reply</button><input type="file" name="attachment" accept="image/*,.svg,.html,.txt" multiple></form><form method="post" action="/api/thread-state"><input type="hidden" name="thread" value="{{.ID}}"><input type="hidden" name="target" value="{{.Target}}"><input required name="author" placeholder="Your name"><button name="state" value="{{if eq .State "resolved"}}open{{else}}resolved{{end}}">{{if eq .State "resolved"}}Reopen{{else}}Resolve{{end}}</button></form></article>{{end}}</div>{{end}}{{end}}`
